#include "libraw/libraw.h"
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <algorithm>
void stage(libraw_data_t* r,const char* s){auto &d=*r; fprintf(stderr,"model=%s %s; decoder=%s; FujiCropModeMetadata=%u; FujiGeneration=%d; FujiSizeTable=%u,%u; cblackPattern=%u,%u,%u; rawPitch=%u; color3=%s; color4=%s; gamma=%g,%g; noAutoBright=%d; userQual=%d; fujiRotate=%d\n",d.idata.make,d.idata.model,libraw_unpack_function_name(r),d.makernotes.fuji.CropMode,d.makernotes.fuji.RAFDataGeneration,d.makernotes.fuji.RAFData_ImageSizeTable[0],d.makernotes.fuji.RAFData_ImageSizeTable[1],d.color.cblack[4],d.color.cblack[5],d.color.cblack[6],d.sizes.raw_pitch,d.rawdata.color3_image?"yes":"no",d.rawdata.color4_image?"yes":"no",d.params.gamm[0],d.params.gamm[1],d.params.no_auto_bright,d.params.user_qual,d.params.use_fuji_rotate);printf("{\"stage\":\"%s\",\"version\":\"%s\",\"rawWidth\":%d,\"rawHeight\":%d,\"width\":%d,\"height\":%d,\"top\":%d,\"left\":%d,\"black\":%u,\"white\":%u,\"cblack\":[%u,%u,%u,%u],\"wb\":[%.9g,%.9g,%.9g,%.9g],\"preMul\":[%.9g,%.9g,%.9g,%.9g],\"rgbCam\":[",s,libraw_version(),d.sizes.raw_width,d.sizes.raw_height,d.sizes.width,d.sizes.height,d.sizes.top_margin,d.sizes.left_margin,d.color.black,d.color.maximum,d.color.cblack[0],d.color.cblack[1],d.color.cblack[2],d.color.cblack[3],d.color.cam_mul[0],d.color.cam_mul[1],d.color.cam_mul[2],d.color.cam_mul[3],d.color.pre_mul[0],d.color.pre_mul[1],d.color.pre_mul[2],d.color.pre_mul[3]);for(int a=0;a<3;a++)for(int b=0;b<4;b++)printf("%s%.9g",a||b?",":"",d.color.rgb_cam[a][b]);printf("],\"rawAvailable\":%s",d.rawdata.raw_image?"true":"false");if(d.rawdata.raw_image){uint64_t n=(uint64_t)d.sizes.raw_height*d.sizes.raw_pitch/2,sum=0;unsigned lo=65535,hi=0;for(uint64_t i=0;i<n;i++){unsigned v=d.rawdata.raw_image[i];sum+=v;lo=std::min(lo,v);hi=std::max(hi,v);}printf(",\"sensorMin\":%u,\"sensorMax\":%u,\"sensorSum\":%llu,\"samplesIncludingPitch\":%llu",lo,hi,(unsigned long long)sum,(unsigned long long)n);}printf("}\n");fflush(stdout);}
int main(int argc,char** argv){if(argc!=4)return 2;libraw_data_t* rp=libraw_init(0);auto &r=*rp;int e=libraw_open_file(rp,argv[1]);if(e){printf("{\"error\":%d,\"at\":\"open\"}\n",e);return 3;}stage(rp,"container");e=libraw_unpack(rp);if(e)return 4;stage(rp,"unpack-before-black");auto &p=r.params;p.use_camera_wb=1;p.use_auto_wb=0;p.use_camera_matrix=1;p.output_color=1;p.output_bps=16;p.output_tiff=1;p.user_flip=0;p.half_size=0;p.user_qual=3;p.no_auto_bright=1;p.use_fuji_rotate=atoi(argv[3]);e=libraw_dcraw_process(rp);if(e){printf("{\"error\":%d,\"at\":\"process\"}\n",e);return 5;}stage(rp,"processed");e=libraw_dcraw_ppm_tiff_writer(rp,argv[2]);return e?6:0;}
